CREATE TABLE IF NOT EXISTS playground_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),owner_id uuid NOT NULL REFERENCES users(id),title text NOT NULL,messages jsonb NOT NULL DEFAULT '[]'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS playground_org_owner ON playground_sessions(organization_id,owner_id);
CREATE TABLE IF NOT EXISTS model_import_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),requested_by uuid NOT NULL REFERENCES users(id),repository_id text NOT NULL,status text NOT NULL DEFAULT 'operator_review' CHECK(status IN ('operator_review','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),cancelled_at timestamptz);
